    "dp.title": "Tagesrätsel",
    "dp.menu": "Tagesrätsel",
    "dp.play": "Heutiges Rätsel",
    "dp.done": "Heutiges Rätsel gelöst!",
    "dp.come_back": "Morgen wartet ein neues Rätsel.",
    "dp.streak": "Serie: {n} Tage",
    "dp.best": "Rekord: {n}",
    "dp.trophies": "Pokale: {n}",
    "dp.trophy_won": "Der Tagespokal gehört dir!",
